from typing import Hashable, Mapping, TypeVar

P = TypeVar("P", bound=Hashable)
Q = TypeVar("Q", bound=Hashable)

def transfer_intersection_number(
    correspondence: Mapping[P, Q],
    classical_multiplicity: Mapping[P, int],
    tropical_multiplicity: Mapping[Q, int],
) -> int:
    """Validate a weighted bijection and return the common intersection number."""
    if set(correspondence) != set(classical_multiplicity):
        raise ValueError("source support mismatch")
    image = set(correspondence.values())
    if len(image) != len(correspondence) or image != set(tropical_multiplicity):
        raise ValueError("correspondence is not a bijection onto the target support")
    for p, q in correspondence.items():
        if classical_multiplicity[p] != tropical_multiplicity[q]:
            raise ValueError("multiplicity is not preserved")
    return sum(classical_multiplicity.values())

